public class Main {
    private static int toMinutes(String time) {
        String[] parts = time.split(":");
        int h = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        return h * 60 + m;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int a = sc.nextInt();
        int ta = sc.nextInt();
        int b = sc.nextInt();
        int tb = sc.nextInt();
        String depTime = sc.next();

        int simStart = toMinutes(depTime);
        int simEnd = simStart + ta;

        int dayStart = 5 * 60;          // 05:00
        int dayEnd = 24 * 60 - 1;       // 23:59

        int count = 0;

        // Iterate over all departures from B
        for (int t = dayStart; t <= dayEnd; t += b) {
            int busStart = t;
            int busEnd = t + tb;

            // Check if intervals [simStart, simEnd] and [busStart, busEnd] intersect
            if (busEnd >= simStart && busStart <= simEnd) {
                // Exclude meeting exactly at start or end city times
                if (!(busEnd == simStart || busStart == simEnd)) {
                    count++;
                }
            }
        }

        System.out.println(count);
    }
}

