        int sm = Integer.parseInt(timeStr.substring(3, 5));
        int simStart = sh * 60 + sm;
        int simEnd = simStart + ta - 1; // inclusive interval [simStart, simEnd]

        int count = 0;

        // Iterate over all buses from B to A
        for (int depart = DAY_START; depart <= DAY_END; depart += b) {
            int busStart = depart;
            int busEnd = depart + tb - 1;

            // Check intersection of [busStart, busEnd] with [simStart, simEnd]
